patch:
diff --git a/src/compiler/cgir/mc_lowering.h b/src/compiler/cgir/mc_lowering.h
index 002ba7b..b210217 100644
--- a/src/compiler/cgir/mc_lowering.h
+++ b/src/compiler/cgir/mc_lowering.h
@@ -32,8 +32,18 @@ public:
       ZEN_UNREACHABLE();
     }
     Streamer = std::move(*StreamerOrErr);
+    reinitialize();
+  }
+
+  // Initialize sections on a fresh/reset context after prior streamer reset.
+  void reinitialize() {
+    MF = nullptr;
+#if defined(ZEN_ENABLE_LINUX_PERF) && defined(ZEN_ENABLE_EVM)
+    LastBBSymbol = nullptr;
+#endif
     TM.getObjFileLowering()->Initialize(Context, TM);
     Streamer->initSections(false, *STI);
+    StreamerIsReset = false;
 #if defined(ZEN_ENABLE_LINUX_PERF) && defined(ZEN_ENABLE_EVM)
     // Because actual dwarf source is evm bytecode, set to ./evm-bytecode
     // as a placeholder whether or not this file exists.
@@ -44,7 +54,20 @@ public:

   void finalize() {
     Streamer->finish();
-    Streamer->reset();
+    reset();
+  }
+
+  // Also discard an unfinished object if a previous compile did not finalize.
+  // This must happen before MCContext::reset invalidates symbols/fragments.
+  void reset() {
+    if (!StreamerIsReset) {
+      Streamer->reset();
+      StreamerIsReset = true;
+    }
+    MF = nullptr;
+#if defined(ZEN_ENABLE_LINUX_PERF) && defined(ZEN_ENABLE_EVM)
+    LastBBSymbol = nullptr;
+#endif
   }

   void runOnCgFunction(CgFunction &MF) {
@@ -200,6 +223,7 @@ protected:
   llvm::raw_svector_ostream OS;
   std::unique_ptr<llvm::MCStreamer> Streamer;
   const llvm::MCSubtargetInfo *STI = nullptr;
+  bool StreamerIsReset = false;

   // Following fields are used for single function lowering
   CgFunction *MF = nullptr;
diff --git a/src/compiler/context.cpp b/src/compiler/context.cpp
index d71da82..32c380b 100644
--- a/src/compiler/context.cpp
+++ b/src/compiler/context.cpp
@@ -167,15 +167,13 @@ void CompileContext::finalize() {
 void CompileContext::reinitialize() {
   ZEN_ASSERT(MCL);
   ZEN_ASSERT(MCCtx);
-  ThreadMemPool.deleteObject(MCL);
-  ThreadMemPool.deleteObject(MCCtx);
-
-  // Ensure ObjBuffer is empty for upcoming compilation
+  // Reset even an unfinished object before invalidating MC symbols/sections.
+  // A completed object's streamer was already reset by finalize().
   ZEN_ASSERT(ObjBuffer.empty());
-
-  // All sections in object files are created and stored in MCContext, so we
-  // need to create a new MCContext
-  initializeMC();
+  MCL->reset();
+  MCCtx->reset();
+  MCCtx->setObjectFileInfo(TM->getObjFileLowering());
+  MCL->reinitialize();
 }

 void CompileContext::initializeTargetMachine() {
